/**
 * Orval input transformer for `apps/server/openapi.v2.json`.
 *
 * The contract file is authoritative and generated by `ashyq openapi`; this
 * transformer only papers over two things the generator needs and the Rust
 * side does not guarantee yet:
 *
 *  1. Dangling `$ref`s — utoipa emits a reference for every `#[param]` enum
 *     but only registers schemas that are reachable from a body. Missing
 *     schemas are filled in from `KNOWN_SCHEMAS` (docs/FINDINGS.md #25).
 *  2. Duplicate `operationId`s across tags (`get_run` in `ai` and `code`,
 *     `review_queue`, `export_csv`, `save_draft`) — Orval's tags-split index
 *     re-exports every tag file, so identical names collide. Duplicates are
 *     renamed `<tag>_<operationId>` for every occurrence (deterministic).
 */

const KNOWN_SCHEMAS = {
  ReviewStatus: {
    type: 'string',
    description: 'Queue filter; `needs_grading` is `pending`.',
    enum: ['needs_grading', 'pending', 'graded', 'published', 'returned'],
  },
}

function collectRefs(value, refs) {
  if (Array.isArray(value)) {
    for (const item of value) collectRefs(item, refs)
    return
  }
  if (!value || typeof value !== 'object') return
  for (const [key, child] of Object.entries(value)) {
    if (key === '$ref' && typeof child === 'string') {
      const match = /^#\/components\/schemas\/([A-Za-z0-9_]+)$/u.exec(child)
      if (match) refs.add(match[1])
      continue
    }
    collectRefs(child, refs)
  }
}

function fillDanglingRefs(spec) {
  const schemas = spec.components?.schemas ?? {}
  const refs = new Set()
  collectRefs(spec, refs)
  const missing = [...refs].filter(name => !(name in schemas))
  for (const name of missing) {
    const known = KNOWN_SCHEMAS[name]
    if (!known) {
      throw new Error(`openapi.v2.json references unknown schema "${name}" — add it to KNOWN_SCHEMAS or fix the contract`)
    }
    console.warn(`[orval] filling dangling schema ref "${name}" (contract defect, see docs/FINDINGS.md)`)
    schemas[name] = known
  }
}

function dedupeOperationIds(spec) {
  const seen = new Map()
  for (const [route, methods] of Object.entries(spec.paths ?? {})) {
    for (const [method, operation] of Object.entries(methods)) {
      if (!operation || typeof operation !== 'object' || !operation.operationId) continue
      const list = seen.get(operation.operationId) ?? []
      list.push({ route, method, operation })
      seen.set(operation.operationId, list)
    }
  }
  for (const [operationId, occurrences] of seen) {
    if (occurrences.length < 2) continue
    for (const { operation } of occurrences) {
      const tag = (operation.tags?.[0] ?? 'default').replace(/[^a-z0-9]+/giu, '_')
      operation.operationId = `${tag}_${operationId}`
    }
  }
}

export default function transformer(spec) {
  fillDanglingRefs(spec)
  dedupeOperationIds(spec)
  return spec
}
